<?php

declare(strict_types=1);
$data = is_array($data ?? null) ? $data : [];
$record = is_array($record ?? null) ? $record : [];

$v = static fn(string $key, string $default=''): string => trim((string) ($data[$key] ?? $default));
$money = static fn(string $key): string => number_format((float) ($data[$key] ?? 0), 2, ',', '.');
$checked = static fn(string $value, array $needles): string => in_array(strtolower(trim($value)), array_map('strtolower',$needles), true) ? 'checked' : '';
$date = $v('transaction_date');
if ($date !== '') { $ts=strtotime($date); if ($ts!==false) $date=date('d/m/Y',$ts); }
